'use strict';

var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var vector = require( '@stdlib/ndarray/vector/ctor' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var ndarray2array = require( '@stdlib/ndarray/to-array' );
var ggemv = require( './../lib' );

var opts = {
	'dtype': 'generic'
};

var A = new ndarray( 'generic', discreteUniform( 12, 0, 10, opts ), [ 3, 4 ], [ 4, 1 ], 0, 'row-major' );
console.log( ndarray2array( A ) );

var x = vector( discreteUniform( 4, 0, 10, opts ), 'generic' );
console.log( ndarray2array( x ) );

var y = vector( discreteUniform( 3, 0, 10, opts ), 'generic' );
console.log( ndarray2array( y ) );

var alpha = scalar2ndarray( 3.0, opts );
var beta = scalar2ndarray( 2.0, opts );

var out = ggemv( [ A, x, y, alpha, beta ] );
console.log( ndarray2array( out ) );
